// function processData(data) mein object do
// Agar data nahi: null
// Agar data.users nahi: null
// Agar data.users array nahi: null
// Warna users ki names array return karo

solution:
function processData(data) {
  if (!data) return null
  if (!data.users) return null
  if (!Array.isArray(data.users)) return null
  return data.users.map(u => u.name).filter(Boolean)
}
